local function bufferline_diagnostics(kind, color)
  hl_many({
    "BufferLine" .. kind,
    "BufferLine" .. kind .. "Diagnostic",
    "BufferLine" .. kind .. "Visible",
    "BufferLine" .. kind .. "DiagnosticVisible",
  }, { fg = color, bg = c.bg_alt })
  hl_many({
    "BufferLine" .. kind .. "Selected",
    "BufferLine" .. kind .. "DiagnosticSelected",
  }, { fg = color, bg = c.selection })
end

bufferline_diagnostics("Error", c.red)
bufferline_diagnostics("Warning", c.yellow)
bufferline_diagnostics("Info", c.info)
bufferline_diagnostics("Hint", c.info)
